// Pisca LED: acende e apaga o LED do pino 13
void setup() {
  pinMode(13, OUTPUT);   // pino 13 como saída
}

void loop() {
  digitalWrite(13, HIGH); // acende
  delay(1000);            // espera 1 segundo
  digitalWrite(13, LOW);  // apaga
  delay(1000);
}

exemplo:
// Versão organizada, com constantes e mensagens no monitor serial
const int pinoLed = 13;
const int tempo = 500; // meio segundo

void setup() {
  pinMode(pinoLed, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  digitalWrite(pinoLed, HIGH);
  Serial.println("LED aceso");
  delay(tempo);
  digitalWrite(pinoLed, LOW);
  Serial.println("LED apagado");
  delay(tempo);
}
